/* Fullstack Academy preview: no server, user code execution or external dependencies. */
(() => {
  'use strict';
  const AUTHOR_IDS = ['06.01.01', '07.02.01', '09.01.02', '15.02.04'];
  const LESSONS = {
    '06.01.01': {
      headline:'JSX: Describe a UI without manually building the DOM', subtitle:'The syntax that makes React components readable',minutes:35,level:'Beginner',
      intro:'You could create dozens of DOM nodes manually, or describe the interface as a function of data. JSX gives React a compact way to express that structure. It resembles HTML, but it is transformed into JavaScript.',
      objectives:['Explain how JSX becomes JavaScript React can use','Return valid markup from a component','Embed expressions inside curly braces','Render a list with stable keys'],
      nodes:['Write JSX','Compile to JavaScript','React updates DOM'],
      steps:[
       {title:'Describe the interface',copy:'A React component is a function that returns JSX. Components let us compose predictable UI pieces.',file:'src/TeamCard.tsx',code:'export function TeamCard() {\n  return (\n    <article>\n      <h2>Engineering team</h2>\n      <p>People building things together.</p>\n    </article>\n  );\n}'},
       {title:'Embed values from JavaScript',copy:'Curly braces enter JavaScript expressions. You can render variables or compute a label without constructing HTML strings.',file:'src/TeamCard.tsx',code:'const team = "Platform Crew";\nconst count = 4;\nreturn <p>{team} has {count} members.</p>;'},
       {title:'Render lists from real data',copy:'Give each mapped item a stable key. Index keys can move state to the wrong item when a list is reordered.',file:'src/TeamCard.tsx',code:'const people = [{id:"p1",name:"Ava"},{id:"p2",name:"Noel"}];\nreturn <ul>{people.map(person =>\n  <li key={person.id}>{person.name}</li>\n)}</ul>;'},
       {title:'Understand JSX attribute differences',copy:'In JSX, use className instead of class; htmlFor instead of for. A style prop takes a JavaScript object.',file:'src/SampleForm.tsx',code:'return <div className="field">\n  <label htmlFor="display-name">Name</label>\n  <input id="display-name" style={{ borderRadius: 8 }} />\n</div>;'}
      ],
      quiz:{question:'What happens to JSX in a typical modern React build?',choices:['Browsers execute JSX syntax directly','Build tooling transforms JSX into React-compatible JavaScript','JSX is a CSS stylesheet','JSX is automatically a plain HTML string'],answer:1,explanation:'Correct. A compiler transforms JSX syntax into JavaScript calls consumed by React. It is not a literal HTML string.'},
      lab:{title:'Build a skill card component',description:'Accept a title, level and a skills array. Render values using JSX expressions and the skills list using .map() with stable IDs.',rubric:['My JSX tags are properly closed','My data is passed into a reusable component','The skills list uses stable keys','The example compiles with my React starter'],hint:'Use skills.map(skill => <li key={skill.id}>{skill.label}</li>) and put the results inside a <ul>.',solution:'type Skill = {id:string;label:string};\nfunction SkillCard({ skills }:{ skills:Skill[] }) {\n  return <ul>{skills.map(s =>\n    <li key={s.id}>{s.label}</li>\n  )}</ul>;\n}'},
      bug:{title:'An input moves to the wrong row',symptom:'After reordering a list, typed text appears next to a different item. The list uses key={index}.',diagnosis:'React tracks identity by keys. Array positions change when rows move, so index keys can associate state with the wrong item. Use a stable key from the data.'},
      reflection:'How is declaring UI as JSX different from manually appending DOM elements?',sources:[['Writing Markup with JSX','https://react.dev/learn/writing-markup-with-jsx'],['Rendering Lists','https://react.dev/learn/rendering-lists']]
    },
    '09.01.02': {
      headline:'Why TypeScript cannot validate an API response', subtitle:'The missing safety net between your code and the real world',minutes:35,level:'Intermediate',
      intro:'Imagine your API says a user has an age. TypeScript trusts the type you wrote, but the network can send a string, a null, or a missing value. That gap is exactly what runtime validation closes.',
      objectives:['Explain why TypeScript does not validate network responses','Build a Zod 4 schema for untrusted JSON','Use safeParse to handle success and failure without throwing','Write a negative test for invalid external data'],
      nodes:['Unknown JSON','Zod schema','Typed data or errors'],
      steps:[
        {title:'Start with data you cannot trust',copy:'A response from fetch() is not proven correct just because you declared a TypeScript interface. Start with unknown; require proof before accessing fields.',code:'type User = { name: string; age: number };\n\nconst payload: unknown = {\n  name: "Mika",\n  age: "twenty"\n};',file:'src/index.ts'},
        {title:'Define the rules in Zod',copy:'Create one runtime schema. Infer a TypeScript type from it so your runtime and compile-time expectations stay aligned.',code:'import * as z from "zod";\n\nconst UserSchema = z.object({\n  name: z.string().min(1),\n  age: z.number().int().nonnegative()\n});\n\ntype User = z.infer<typeof UserSchema>;',file:'src/index.ts'},
        {title:'Parse, then make a decision',copy:'safeParse returns a result with a success flag. A failure is data you can handle, not an accidental crash.',code:'const result = UserSchema.safeParse(payload);\n\nif (!result.success) {\n  console.log(result.error.issues);\n} else {\n  console.log(result.data.name);\n}',file:'src/index.ts'},
        {title:'Prove both paths work',copy:'Run with age set to 20. Then try -1, 20.5 and "20". Your test should reject every invalid variation.',code:'// Predict the output BEFORE running:\nUserSchema.safeParse({name:"A",age:20}).success; // true\nUserSchema.safeParse({name:"A",age:"20"}).success; // false',file:'src/index.ts'}
      ],
      quiz:{question:'Why is `const user = json as User` unsafe for data received from an API?',choices:['TypeScript automatically converts values at runtime','A type assertion does not validate the JSON shape','Fetch can never return a JSON object','All type assertions throw exceptions'],answer:1,explanation:'Correct. `as User` is a compile-time assertion; it does not inspect or transform a value. Validate at the trust boundary instead.'},
      lab:{title:'Build a safe product parser',description:'Create a ProductSchema with a nonempty ID, a nonnegative price and an array of strings for tags. Test one valid and three invalid payloads.',rubric:['I wrote a runtime schema, not only an interface','The parser accepts one valid fixture','The parser rejects missing ID and negative price','I can explain why unknown is safer than any'],hint:'Start with z.object({ id: z.string().min(1), price: z.number().nonnegative(), tags: z.array(z.string()) }).',solution:'const ProductSchema = z.object({\n  id: z.string().min(1),\n  price: z.number().nonnegative(),\n  tags: z.array(z.string())\n});'},
      bug:{title:'The number input that is still a string',symptom:'A user enters 12 in an HTML <input type="number">, but z.number() rejects the value.',diagnosis:'Form values are commonly strings. Parse intentionally or use controlled coercion with careful empty-input handling. Do not assume a type attribute converts JS values.'},
      reflection:'Where else would you validate unknown values besides an API response?',sources:[['Zod 4 basics','https://zod.dev/basics'],['Zod API','https://zod.dev/api']]
    },
    '07.02.01':{
      headline:'Where should this code run?',subtitle:'Server Components, Client Components, and the boundary between them',minutes:40,level:'Intermediate',
      intro:'You want a fast page that fetches data and responds to a click. Putting everything in the browser means more JS and bigger security risks. Putting everything on the server means you still need an interactive island. Let’s separate responsibilities.',
      objectives:['Identify Server and Client Components in Next.js App Router','Place stateful interaction in a small client boundary','Pass serializable props from server to client','Keep server-only secrets out of browser code'],nodes:['Server rendering','Serializable props','Interactive client island'],
      steps:[
       {title:'Keep page rendering on the server',copy:'App Router pages are Server Components by default. An async component can gather safe data for rendering.',file:'app/projects/page.tsx',code:'import { Counter } from "./counter";\n\nexport default async function ProjectsPage() {\n  const projects = ["Atlas", "Orbit"];\n  return <main><h1>Projects</h1>\n    {projects.map(p => <p key={p}>{p}</p>)}\n    <Counter />\n  </main>;\n}'},
       {title:'Put state where interaction happens',copy:'Only the interactive counter needs a client boundary. The rest of the page can remain server-rendered.',file:'app/projects/counter.tsx',code:'"use client";\nimport { useState } from "react";\n\nexport function Counter() {\n  const [n,setN] = useState(0);\n  return <button onClick={() => setN(x => x + 1)}>\n    Clicked {n} times\n  </button>;\n}'},
       {title:'Try the wrong boundary',copy:'Move useState into the async Server Component and inspect the compilation error. Return it to a small Client Component.',file:'app/projects/page.tsx',code:'// Do NOT move stateful hooks into a Server Component.\n// Instead keep <Counter /> as a client boundary.'}
      ],
      quiz:{question:'Which part of a Next.js App Router page needs `"use client"`?',choices:['Every page, or React will not work','A component that uses useState and browser events','Every component that uses JSX','Any component that reads data from a server'],answer:1,explanation:'Correct. `"use client"` defines a boundary for interactive browser behavior. App Router Server Components are the default.'},
      lab:{title:'Server-render the projects, client-filter the list',description:'Pass safe project objects from a Server Component to a client-side filter. Keep credentials and data fetching on the server.',rubric:['The page loads with project data','The client filter changes the visible list','Only interactive code is in the client boundary','No server-only secrets are included in client code'],hint:'Create a `ProjectList` component with `"use client"`, pass it a serializable array of {id,title}, and filter with useState.',solution:'// Server page: <ProjectList projects={projects} />\n// Client component: const [query,setQuery] = useState("");\n// const visible = projects.filter(p => p.title.includes(query));'},
      bug:{title:'A database client imported into the browser',symptom:'A client component imports a server-side Prisma module and the build fails.',diagnosis:'Move Prisma/database calls to server-only modules. Server components or approved BFF endpoints can pass safe serializable data to the UI.'},
      reflection:'Why does a single search box not justify converting an entire page into a Client Component?',sources:[['Server and Client Components','https://nextjs.org/docs/app/getting-started/server-and-client-components'],['Next.js data security','https://nextjs.org/docs/app/guides/data-security']]
    },
    '15.02.04':{
      headline:'The authorization bug that slips past login',subtitle:'Valid identity is not the same as permission to access a record',minutes:45,level:'Advanced',
      intro:'A user signs in and loads project /projects/a. Now they change the URL to /projects/b. If B belongs to another organization, a valid token must not grant access. That is object-level authorization, and forgetting it is a serious bug.',
      objectives:['Separate authentication from object-level authorization','Recognize vulnerable record lookup queries','Apply tenant-scoped predicates in Prisma','Write negative tests for cross-tenant access'],nodes:['Verified identity','Resource policy','Tenant-scoped query'],
      steps:[
       {title:'Spot the vulnerable lookup',copy:'This query is intentionally unsafe. It fetches a resource by ID without verifying that the principal is allowed to read it.',file:'projects.service.ts',code:'// INSECURE: no tenant or resource scope\nconst project = await prisma.project.findUnique({\n  where: { id: projectId }\n});'},
       {title:'Derive an authorized organization',copy:'Only accept an organization as an authorized scope AFTER verifying the principal belongs to it and has read permission.',file:'projects.service.ts',code:'const authorizedOrganizationId =\n  await permissions.requireOrgAccess(principal, requestedOrgId, "project:read");'},
       {title:'Scope the database access',copy:'The exact response policy may choose a 403 or 404 for unauthorized resources. It must never return the record.',file:'projects.service.ts',code:'const project = await prisma.project.findFirst({\n  where: { id: projectId,\n    organizationId: authorizedOrganizationId },\n  select: { id:true, title:true }\n});\nif (!project) throw new NotFoundException();'},
       {title:'Prove the negative case',copy:'Create users A and B in different organizations. Verify A can read their own project but cannot read or mutate B’s project even when the ID is known.',file:'projects.e2e-spec.ts',code:'// Accept: A -> A (200)\n// Deny:   A -> B (403 or 404)\n// Deny:   A -> B with B org ID in request body\n// Deny:   A -> B mutation'}
      ],
      quiz:{question:'An endpoint verifies a valid JWT but loads any project ID. What is missing?',choices:['A faster database index','Object-level authorization against the requested resource','An animation loading state','More TypeScript types'],answer:1,explanation:'Correct. Authentication proves identity; policy checks must verify the caller can access this specific resource.'},
      lab:{title:'Write the missing negative tests',description:'Create two organizations and two users. Test own-tenant reads, forbidden foreign-tenant reads, and foreign-tenant writes.',rubric:['I defined the resource permission','I verified membership server-side','Cross-tenant read is denied','Cross-tenant mutation is denied'],hint:'Do not trust organizationId supplied in the body. Check membership of the verified principal against the requested organization.',solution:'// Pseudocode:\nawait permissions.requireOrgAccess(principal, orgId, "project:read");\nconst found = await prisma.project.findFirst({where:{id,organizationId:orgId}});'},
      bug:{title:'The valid-token IDOR',symptom:'A security test authenticates User A and requests User B’s real project ID. It unexpectedly returns 200 and private data.',diagnosis:'The authentication guard verifies the token but the database query omits resource policy checks. Add verified membership + permission + tenant scoping and a regression test.'},
      reflection:'Where else can object-level authorization be forgotten (attachments, exports, WebSocket events, background jobs)?',sources:[['OWASP API security','https://owasp.org/API-Security/'],['NestJS Guards','https://docs.nestjs.com/guards'],['Supabase RLS','https://supabase.com/docs/guides/database/postgres/row-level-security']]
    }
  };
  const fullTracks = CATALOG.tracks;
  const lessonMap = new Map(CATALOG.lessons.map(l=>[l.id,l]));
  const moduleMap = new Map(CATALOG.modules.map(m=>[m.id,m]));
  const reference = CATALOG.reference;
  const storageKey = 'fullstack-academy-preview-v1';
  let saved={complete:{},quizzes:{},rubrics:{},notes:{},theme:'light',reflections:{}};
  try {const prior=JSON.parse(localStorage.getItem(storageKey)||'null');if(prior && typeof prior==='object') saved={...saved,...prior};}catch{}
  let sidebarTab='curriculum',selected='06.01.01',openTrack='09',openModule='09.01',searchTerm='',view='lesson',activeReference=null,bugRevealed=false,solutionShown=false,hintShown=false;
  const $=s=>document.querySelector(s);
  const main=$('#main-content'),nav=$('#sidebar-list'),search=$('#search'),toc=$('#local-toc'),note=$('#quick-note');
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const persist=()=>{try{localStorage.setItem(storageKey,JSON.stringify(saved))}catch{}};
  const authoredCount=AUTHOR_IDS.length;
  const moduleLessons=(id)=>CATALOG.lessons.filter(l=>l.moduleId===id);
  const trackModules=(id)=>CATALOG.modules.filter(m=>m.track===id);
  function updateProgress(){const done=AUTHOR_IDS.filter(id=>saved.complete[id]).length;$('#progress-tally').textContent=`${done} / ${authoredCount}`;$('#progress-fill').style.width=`${done/authoredCount*100}%`;$('#progress-subline').textContent=`${CATALOG.lessons.length} topics mapped · ${authoredCount} authored drafts`;}
  function setTab(tab){sidebarTab=tab;search.value='';searchTerm='';document.querySelectorAll('[data-sidebar-tab]').forEach(btn=>{let active=btn.dataset.sidebarTab===tab;btn.classList.toggle('active',active);btn.setAttribute('aria-selected',String(active))});renderNav();}
  function renderNav(){nav.innerHTML='';const q=searchTerm.toLowerCase().trim();if(sidebarTab==='notes'){let ids=Object.keys(saved.notes).filter(id=>saved.notes[id]?.trim());nav.innerHTML=`<div class="list-label">PRIVATE NOTES · ${ids.length}</div>`;for(const id of ids){const b=document.createElement('button');b.className='result-item';b.textContent=(lessonMap.get(id)?.title || id);const sm=document.createElement('small');sm.textContent=saved.notes[id].slice(0,100);b.append(sm);b.onclick=()=>selectLesson(id);nav.append(b)}if(!ids.length)nav.innerHTML+='<p class="small muted" style="padding:0 12px">Notes saved in the reader appear here.</p>';return;}
    if(sidebarTab==='reference'){const list=reference.filter(r=>!q || `${r.category} ${r.title}`.toLowerCase().includes(q)).slice(0,130);nav.innerHTML=`<div class="list-label">REFERENCE ENCYCLOPEDIA · ${q?list.length+' results':reference.length+' indexed subjects'}</div>`;for(const ref of list){const b=document.createElement('button');b.className='result-item';b.innerHTML=`${esc(ref.title)}<small>${esc(ref.category)}</small>`;b.onclick=()=>selectReference(ref);nav.append(b)}return;}
    if(q){const list=CATALOG.lessons.filter(l=>`${l.track} ${l.module} ${l.title} ${l.id}`.toLowerCase().includes(q)).slice(0,120);nav.innerHTML=`<div class="list-label">LESSON SEARCH · ${list.length}${list.length===120?'+':''} MATCHES</div>`;for(const l of list){const b=document.createElement('button');b.className='result-item';b.innerHTML=`${esc(l.title)}<small>${esc(l.id)} · ${esc(l.module)}${LESSONS[l.id]?' · Sample authored':''}</small>`;b.onclick=()=>selectLesson(l.id);nav.append(b)}if(!list.length)nav.innerHTML+='<div class="small muted" style="padding:12px">No matches. Try fewer words.</div>';return;}
    const lab=document.createElement('div');lab.className='list-label';lab.textContent=`${fullTracks.length} TRACKS · ${CATALOG.modules.length} MODULES`;nav.append(lab);
    for(const t of fullTracks){const block=document.createElement('div');block.className='track '+(openTrack===t.id?'track-open':'');const head=document.createElement('button');head.className='track-head';head.setAttribute('aria-expanded',String(openTrack===t.id));head.innerHTML=`<span class="track-num">${esc(t.id)}</span><span class="track-name">${esc(t.title)}<br><span class="track-count">${trackModules(t.id).length} modules · ${CATALOG.lessons.filter(l=>l.trackId===t.id).length} topics</span></span><span aria-hidden="true">${openTrack===t.id?'⌃':'⌄'}</span>`;head.onclick=()=>{openTrack=openTrack===t.id?'':t.id;renderNav()};block.append(head);
      if(openTrack===t.id){const modWrap=document.createElement('div');modWrap.className='track-modules';for(const m of trackModules(t.id)){const btn=document.createElement('button');btn.className='module-head';btn.textContent=`${m.id} · ${m.title} (${m.lessonCount})`;btn.setAttribute('aria-expanded',String(openModule===m.id));btn.onclick=()=>{openModule=openModule===m.id?'':m.id;renderNav()};modWrap.append(btn);if(openModule===m.id){for(const l of moduleLessons(m.id)){const a=document.createElement('button');a.className='lesson-nav '+(selected===l.id&&view==='lesson'?'active':'');a.innerHTML=`<span>${esc(l.title)}</span><span class="pill-mini ${LESSONS[l.id]?'ready':''}">${saved.complete[l.id]?'✓':LESSONS[l.id]?'sample':'·'}</span>`;a.onclick=()=>selectLesson(l.id);modWrap.append(a)}}}block.append(modWrap)}nav.append(block)}
  }
  function setNoteContext(){note.value=(saved.notes[selected]||'');note.disabled=view!=='lesson';$('#note-feedback').textContent=view==='lesson'?'Saved locally on this device':'Open a lesson to write a private note';}
  function updateTOC(){toc.innerHTML='';main.querySelectorAll('h2[id],h3[id]').forEach(h=>{const a=document.createElement('a');a.href='#'+h.id;a.textContent=h.textContent;toc.append(a)});}
  function breadcrumbs(){const l=lessonMap.get(selected);$('#breadcrumbs').innerHTML=view==='reference'?'ACADEMY <span>/</span> REFERENCE':view==='arena'?'ACADEMY <span>/</span> BUG HUNT':view==='welcome'?'ACADEMY <span>/</span> OVERVIEW':`ACADEMY <span>/</span> ${esc(l?.track||'LESSON')} <span>/</span> ${esc(selected)}`;}
  function load(){document.body.dataset.theme=saved.theme||'light';updateProgress();renderNav();setNoteContext();breadcrumbs();renderView();}
  function selectLesson(id){selected=id;view='lesson';const l=lessonMap.get(id);if(l){openTrack=l.trackId;openModule=l.moduleId;}bugRevealed=false;solutionShown=false;hintShown=false;$('#sidebar').classList.remove('show');load();window.scrollTo(0,0);}
  function selectReference(ref){activeReference=ref;view='reference';$('#sidebar').classList.remove('show');load();window.scrollTo(0,0);}
  function copyCode(btn){const text=btn.closest('.code-frame').querySelector('code').textContent;navigator.clipboard?.writeText(text).then(()=>{btn.textContent='Copied ✓';setTimeout(()=>btn.textContent='Copy',1000)}).catch(()=>{btn.textContent='Select text to copy'});}
  function codeBlock(contents,file){return `<div class="code-frame"><div class="code-toolbar"><span>⌘ &nbsp;${esc(file||'example.ts')}</span><button class="copy-code" type="button">Copy</button></div><pre><code>${esc(contents)}</code></pre></div>`;}
  function renderLesson(){const l=lessonMap.get(selected),p=LESSONS[selected];if(!l){main.innerHTML='<h1>Lesson unavailable</h1>';return}
    if(!p){main.innerHTML=`<div class="eyebrow">${esc(l.track)} / ${esc(l.module)}</div><h1>${esc(l.title)}</h1><p class="subtitle">Syllabus entry ${esc(l.id)} · Planned teaching content</p><div class="callout warning"><strong>Not yet authored.</strong> This topic is part of the complete curriculum map, but its tutorial, code lab, verification and quiz are not published. No fake completion or empty filler.</div><div class="section-card"><h3>Module learning objective</h3><p class="copy">${esc(moduleMap.get(l.moduleId)?.outcome||'Learn and apply this concept safely.')}</p><p class="small muted">Original official documentation: <a href="${esc(l.referenceUrl)}" target="_blank" rel="noopener noreferrer">Open reference ↗</a></p></div><div class="button-row"><button class="btn-secondary" id="pick-sample">Open an authored sample lesson</button><button class="btn-secondary" id="curriculum-overview">Explore the course map</button></div>`;$('#pick-sample').onclick=()=>selectLesson('06.01.01');$('#curriculum-overview').onclick=()=>{view='welcome';load()};return;}
    const completed=Boolean(saved.complete[selected]),quizPassed=Boolean(saved.quizzes[selected]),checks=saved.rubrics[selected]||[];const allChecked=p.lab.rubric.every((_,i)=>checks.includes(i));
    main.innerHTML=`<div class="eyebrow">${esc(l.track)} &nbsp; / &nbsp; ${esc(l.module)}</div><h1>${esc(p.headline)}</h1><p class="subtitle">${esc(p.subtitle)}</p><div class="hero-tag"><span>◷ ${p.minutes} min estimate</span><span class="dot"></span><span>${esc(p.level)}</span><span class="dot"></span><span class="tag">Authored sample · unverified lab</span></div>
      <div class="section-card"><h3 id="objectives">What you'll learn</h3><ul class="objectives">${p.objectives.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>
      <section class="copy"><h2 id="problem">The problem we're solving</h2><p>${esc(p.intro)}</p><h2 id="mental">The mental model</h2><p>Notice the boundaries. Each step has a single responsibility. Changing one boundary without thinking about the next is how surprising bugs appear.</p><div class="mental-flow">${p.nodes.map((n,i)=>`${i?'<span class="mental-arrow" aria-hidden="true">→</span>':''}<div class="mental-node">${esc(n)}</div>`).join('')}</div><div class="callout"><strong>Predict first.</strong> Before running any step, say what you expect. When reality differs, that difference is where you learn.</div></section>
      <section class="copy"><h2 id="walkthrough">Let's build it, one step at a time</h2><div class="stepper">${p.steps.map((s,i)=>`<div class="step-block" data-step="${i+1}"><h3>${esc(s.title)}</h3><p>${esc(s.copy)}</p>${codeBlock(s.code,s.file)}</div>`).join('')}</div></section>
      <section class="copy"><h2 id="quiz">Knowledge check</h2><div class="section-card"><h3>${esc(p.quiz.question)}</h3><div class="quiz-options">${p.quiz.choices.map((c,i)=>`<button class="quiz-option" data-quiz="${i}" aria-pressed="${i===p.quiz.answer&&quizPassed?'true':'false'}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(c)}</span></button>`).join('')}</div><div class="feedback" id="quiz-feedback">${quizPassed?'✓ '+esc(p.quiz.explanation):'Choose your answer. You can retry.'}</div></div></section>
      <section class="copy"><h2 id="lab">Guided challenge</h2><div class="section-card"><h3>${esc(p.lab.title)}</h3><p>${esc(p.lab.description)}</p><div class="button-row"><button class="btn-secondary" id="hint-toggle">${hintShown?'Hide hint':'Show hint'}</button><button class="btn-secondary" id="solution-toggle">${solutionShown?'Hide solution':'Show solution'}</button></div>${hintShown?`<div class="callout"><strong>Hint:</strong> ${esc(p.lab.hint)}</div>`:''}${solutionShown?codeBlock(p.lab.solution,'solution.ts'):''}<h3>Self-assessed rubric</h3><p class="small muted">These checkboxes are self-reported. They do not execute or grade your code in this prototype.</p><div class="rubric">${p.lab.rubric.map((r,i)=>`<label><input type="checkbox" data-rubric="${i}" ${checks.includes(i)?'checked':''}/><span>${esc(r)}</span></label>`).join('')}</div></div></section>
      <section class="copy"><h2 id="bug">Bug Hunt Arena</h2><div class="section-card"><h3>${esc(p.bug.title)}</h3><p>${esc(p.bug.symptom)}</p><button class="btn-secondary" id="bug-toggle">${bugRevealed?'Hide diagnosis':'Reveal diagnosis'}</button>${bugRevealed?`<div class="callout"><strong>What went wrong:</strong> ${esc(p.bug.diagnosis)}</div>`:''}</div></section>
      <section class="copy"><h2 id="reflect">Reflect</h2><p>${esc(p.reflection)}</p><textarea class="reflection-field" style="width:100%;border:1px solid var(--border);border-radius:10px;background:var(--paper);color:var(--text);padding:13px;font-size:13px;min-height:80px;resize:vertical" placeholder="Write your reasoning, not just an answer…">${esc(saved.reflections[selected]||'')}</textarea><p class="small muted">Reflection saved privately in your browser.</p></section>
      <section class="copy"><h2 id="references">Official references</h2>${p.sources.map(s=>`<a class="reference-link" target="_blank" rel="noopener noreferrer" href="${esc(s[1])}">${esc(s[0])}<span>↗</span></a>`).join('')}<p class="small muted">Sample lesson draft. Before publication, commands and labs must be executed against a pinned version with tests.</p></section>
      <section class="section-card"><h3>Finish with evidence</h3><p class="small muted" id="gate-message">${completed?'Already marked complete in this preview.':quizPassed&&allChecked?'Knowledge check passed and rubric self-assessed. You may mark this demo lesson complete.':'Answer the knowledge check and check every rubric item before completing.'}</p><button class="btn-primary" id="complete-lesson" ${!quizPassed||!allChecked||completed?'disabled':''}>${completed?'✓ Sample lesson complete':'Mark sample lesson complete'}</button></section><div class="lesson-footer"><button class="btn-secondary" id="prev">← Previous sample</button><button class="btn-primary" id="next">Next sample →</button></div>`;
    main.querySelectorAll('.copy-code').forEach(b=>b.onclick=()=>copyCode(b));
    main.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>{const guess=Number(b.dataset.quiz);main.querySelectorAll('[data-quiz]').forEach(x=>x.classList.remove('chosen','correct','wrong'));b.classList.add('chosen',guess===p.quiz.answer?'correct':'wrong');if(guess===p.quiz.answer){saved.quizzes[selected]=true;persist();$('#quiz-feedback').textContent='✓ '+p.quiz.explanation}else{$('#quiz-feedback').textContent='Not quite. Re-read the explanation above, then try again.'}renderGateOnly()});
    main.querySelectorAll('[data-rubric]').forEach(b=>b.onchange=()=>{const i=Number(b.dataset.rubric);const set=new Set(saved.rubrics[selected]||[]);b.checked?set.add(i):set.delete(i);saved.rubrics[selected]=[...set];persist();renderGateOnly()});
    $('#hint-toggle').onclick=()=>{hintShown=!hintShown;renderLesson();};$('#solution-toggle').onclick=()=>{solutionShown=!solutionShown;renderLesson();};$('#bug-toggle').onclick=()=>{bugRevealed=!bugRevealed;renderLesson();};
    $('#complete-lesson').onclick=()=>{if(!saved.quizzes[selected]||!p.lab.rubric.every((_,i)=>(saved.rubrics[selected]||[]).includes(i)))return;saved.complete[selected]=true;persist();load()};
    $('.reflection-field').oninput=e=>{saved.reflections[selected]=e.target.value;persist()};
    $('#prev').onclick=()=>selectLesson(AUTHOR_IDS[(AUTHOR_IDS.indexOf(selected)+AUTHOR_IDS.length-1)%AUTHOR_IDS.length]);$('#next').onclick=()=>selectLesson(AUTHOR_IDS[(AUTHOR_IDS.indexOf(selected)+1)%AUTHOR_IDS.length]);
  }
  function renderGateOnly(){const p=LESSONS[selected];const quiz=!!saved.quizzes[selected],all=p.lab.rubric.every((_,i)=>(saved.rubrics[selected]||[]).includes(i));const b=$('#complete-lesson');if(!b)return;b.disabled=!quiz||!all||!!saved.complete[selected];$('#gate-message').textContent=quiz&&all?'Knowledge check passed; rubric self-assessed. You may mark this demo lesson complete.':'Answer the knowledge check and check every rubric item before completing.'}
  function renderWelcome(){main.innerHTML=`<div class="eyebrow">FULL-STACK LEARNING SYSTEM</div><h1>Learn the stack.<br>Understand the system.</h1><p class="subtitle">A hands-on academy designed around real engineering decisions, reproducible code, security, debugging and production readiness—not a checklist of packages.</p><div class="two-up"><div class="metric"><strong>${CATALOG.tracks.length}</strong><small>separate curriculum tracks</small></div><div class="metric"><strong>${CATALOG.modules.length}</strong><small>structured competency modules</small></div><div class="metric"><strong>${CATALOG.lessons.length}</strong><small>planned, individually titled lessons</small></div><div class="metric"><strong>${reference.length}</strong><small>reference subjects indexed</small></div></div><div class="callout warning"><strong>Publishing status:</strong> Curriculum and reference indices are complete as a planning catalog. Only four sample lesson bodies and four reference entries are authored drafts. More content and executable lab tests must be completed before this is a full published course.</div><h2 id="examples">Try a real lesson sample</h2><div class="course-grid">${AUTHOR_IDS.map(id=>{const l=LESSONS[id];return `<article class="course-card"><div class="eyebrow">${id}</div><h3>${esc(l.headline)}</h3><p>${esc(l.subtitle)}</p><button class="btn-secondary" data-open="${id}">Open lesson →</button></article>`}).join('')}</div><h2 id="paths">Choose your learning path</h2><p class="copy">Start with fundamentals or jump directly into the advanced track you want. Prerequisites are recommendations, not artificial lockouts.</p><div class="resource-grid">${['Frontend','Backend','Full stack','Security','DevOps','Mobile and desktop','Advanced systems'].map(x=>`<button class="path-chip">${x}</button>`).join('')}</div><h2 id="why">A lesson isn't complete because you scrolled</h2><p class="copy">Each published lesson must explain a real problem, demonstrate the mental model, show exact files and commands, teach a misconception, provide a bug hunt and require practice. The sample uses honest self-assessment until executable lab grading is added.</p>`;main.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>selectLesson(b.dataset.open));main.querySelectorAll('.path-chip').forEach(b=>b.onclick=()=>{$('#search').value=b.textContent;searchTerm=b.textContent.toLowerCase();setTab('curriculum');$('#search').value=b.textContent;searchTerm=b.textContent.toLowerCase();renderNav()});}
  function renderReference(){const r=activeReference;if(!r){view='welcome';renderWelcome();return}const authors={'zod-safeparse':{heading:'Zod 4: safeParse',syntax:'const result = schema.safeParse(input);',params:'input: unknown — any value to validate against schema.',returns:'Discriminated result with { success: true, data } or { success: false, error }.',minimal:'import * as z from "zod";\nconst AgeSchema = z.number().int().nonnegative();\nconst result = AgeSchema.safeParse("25");\nconsole.log(result.success); // false',production:'const BodySchema = z.object({\n  name: z.string().min(1),\n  email: z.email(),\n});\nconst result = BodySchema.safeParse(body);\nif (!result.success) {\n  return { ok: false as const, errors: z.flattenError(result.error) };\n}\nreturn { ok: true as const, value: result.data };',desc:'Check an unknown value without throwing on an ordinary validation failure. Success returns validated data; failure returns a Zod error.',pitfall:'A TypeScript type assertion (`as Type`) is not runtime validation; browser form inputs remain strings unless parsed/coerced explicitly.',notes:'Validate at every trust boundary (API body, response, webhooks, env). Map failures to a stable public error contract without leaking secrets.',relatedLessons:['09.01.02'],url:'https://zod.dev/basics'},'prisma-transaction':{heading:'Prisma 7: $transaction()',syntax:'await prisma.$transaction(async (tx) => {\n  await tx.account.update({ /* ... */ });\n  await tx.ledgerEntry.create({ /* ... */ });\n});',params:'Callback (tx) => Promise<T> for interactive transactions, or an array of Prisma promises for sequential operations.',returns:'Promise resolving to the return value of the callback or tuple of sequential results; rolls back atomically on error.',minimal:'await prisma.$transaction([\n  prisma.user.update({ where: { id }, data: { active: true } }),\n  prisma.auditLog.create({ data: { actorId: id, action: "activate" } })\n]);',production:'await prisma.$transaction(async (tx) => {\n  const account = await tx.account.findFirstOrThrow({ where: { id, organizationId } });\n  await tx.account.update({ where: { id: account.id }, data: { balance: account.balance - amount } });\n  await tx.outboxEvent.create({ data: { topic: "ledger.debited", payload: { id } } });\n});',desc:'Group dependent database operations into one atomic unit. Keep transactions short and avoid external network calls while inside them.',pitfall:'Database transactions do not automatically guarantee object-level authorization or handle concurrency retries by themselves.',notes:'Never make external HTTP/email calls inside an open DB transaction—use an outbox record instead to keep locks short.',relatedLessons:[],url:'https://www.prisma.io/docs/orm/prisma-client/queries/transactions'},'nestjs-guards':{heading:'NestJS CanActivate / Guards',syntax:'@UseGuards(AuthGuard)\n@Get(":id")\nfindOne() { /* ... */ }',params:'context: ExecutionContext — provides access to the HTTP/WS/RPC request, handler, and class metadata.',returns:'boolean | Promise<boolean> | Observable<boolean> — determines whether the route handler proceeds.',minimal:'@Injectable()\nexport class DemoGuard implements CanActivate {\n  canActivate(context: ExecutionContext): boolean {\n    return Boolean(context.switchToHttp().getRequest().user);\n  }\n}',production:'@UseGuards(JwtAuthGuard, OrgMembershipGuard)\n@Get(":id")\nasync getProject(@Param("id") id: string, @CurrentPrincipal() principal: Principal) {\n  return this.projectsService.findAuthorized(principal, id);\n}',desc:'Guards allow or deny route execution based on trusted request context. Object-level resource policies usually require additional checks in the service.',pitfall:'Checking a valid JWT in a guard is not sufficient to authorize access to every record ID (BOLA/IDOR risk).',notes:'Verify token signatures first, then enforce per-record organization/ownership checks in services and test negative cross-tenant cases.',relatedLessons:['15.02.04'],url:'https://docs.nestjs.com/guards'},'redis-set':{heading:'Redis SET EX',syntax:'SET cache:user:123 "{\\"name\\":\\"Mika\\"}" EX 60',params:'key (namespaced string), value (serialized string/bytes), optional EX seconds or PX milliseconds TTL.',returns:'OK when the key was stored (or nil if NX/XX condition prevented writing).',minimal:'SET cache:org_1:project:9 "{\\"title\\":\\"Atlas\\"}" EX 60',production:'// Cache-aside with tenant-scoped key and bounded TTL\nconst key = `cache:org:${orgId}:project:${projectId}`;\nawait redis.set(key, JSON.stringify(dto), "EX", 60);',desc:'Store a cached string value that expires after a specific number of seconds.',pitfall:'Do not treat temporary cache data as the authoritative system of record or omit tenant scoping in shared keys.',notes:'Separate cache Redis capacity/eviction policy (volatile-lru/allkeys-lru) from durable BullMQ queue Redis instances.',relatedLessons:[],url:'https://redis.io/docs/latest/commands/set/'}};
    const which=r.category==='Zod'&&r.title==='safeParse'?'zod-safeparse':r.category==='Prisma'&&r.title==='$transaction'?'prisma-transaction':r.category==='NestJS'&&(r.title==='CanActivate'||r.title==='@UseGuards')?'nestjs-guards':r.category==='Redis & BullMQ'&&(r.title==='SET'||r.title==='SET EX')?'redis-set':'';
    const a=authors[which];main.innerHTML=`<div class="eyebrow">REFERENCE / ${esc(r.category)}</div><h1>${esc(r.title)}</h1><p class="subtitle">Fast lookup, precise syntax, context, pitfalls and official sources.</p>${a?`<div class="section-card"><h3>At a glance</h3><p class="copy">${esc(a.desc)}</p></div><h2 id="syntax">Syntax</h2>${codeBlock(a.syntax,which.startsWith('redis')?'redis-cli':'example.ts')}<h2 id="parameters">Parameters &amp; Return values</h2><div class="section-card"><p class="copy"><strong>Parameters:</strong> ${esc(a.params)}</p><p class="copy" style="margin-bottom:0"><strong>Returns:</strong> ${esc(a.returns)}</p></div><h2 id="examples">Minimal &amp; Production Examples</h2>${codeBlock(a.minimal,'minimal.ts')}${codeBlock(a.production,'production.ts')}<h2 id="pitfalls">Common mistakes</h2><div class="callout warning">${esc(a.pitfall)}</div><h2 id="notes">Security &amp; Performance Notes</h2><div class="callout">${esc(a.notes)}</div>${a.relatedLessons.length?`<h2 id="related">Related tutorials</h2><div class="button-row">${a.relatedLessons.map(id=>`<button class="btn-secondary" data-open-lesson="${esc(id)}">Open Lesson ${esc(id)} →</button>`).join('')}</div>`:''}<h2 id="source">Canonical documentation</h2><a class="reference-link" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">Open official reference <span>↗</span></a>`:`<div class="callout warning"><strong>Indexed reference — not yet authored.</strong> The ${esc(r.title)} page has a reserved permanent subject identifier, but its signature, examples and tests have not been written.</div><h2 id="outline">Publication requirements</h2><div class="section-card"><ul class="objectives">${['Signature and version information','Parameters and return values','Minimal and production examples','Errors, gotchas and security notes','Related tutorials and official docs'].map(x=>`<li>${x}</li>`).join('')}</ul></div>`}<div class="button-row"><button class="btn-secondary" id="back-ref">Return to curriculum</button></div>`;main.querySelectorAll('.copy-code').forEach(b=>b.onclick=()=>copyCode(b));main.querySelectorAll('[data-open-lesson]').forEach(b=>b.onclick=()=>selectLesson(b.dataset.openLesson));$('#back-ref').onclick=()=>selectLesson(selected);
  }
  function renderArena(){main.innerHTML=`<div class="eyebrow">PRACTICE ZONE</div><h1>Bug Hunt Arena</h1><p class="subtitle">Reading docs teaches the rule. Diagnosing a failure teaches when the rule matters.</p><div class="callout">This prototype contains four authored debug scenarios. In a production course, each drill has a failing starter repo and a test that turns green after the fix.</div>${AUTHOR_IDS.map(id=>{const p=LESSONS[id];return `<article class="course-card"><div class="eyebrow">${id}</div><h3>${esc(p.bug.title)}</h3><p>${esc(p.bug.symptom)}</p><button class="btn-secondary" data-open="${id}">Investigate in lesson →</button></article>`}).join('')}`;main.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>selectLesson(b.dataset.open))}
  function renderView(){if(view==='lesson')renderLesson();else if(view==='reference')renderReference();else if(view==='arena')renderArena();else renderWelcome();updateTOC();}
  search.oninput=()=>{searchTerm=search.value;renderNav()};
  document.querySelectorAll('[data-sidebar-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.sidebarTab));
  $('#jump-unfinished').onclick=()=>selectLesson(AUTHOR_IDS.find(id=>!saved.complete[id])||AUTHOR_IDS[0]);
  $('#open-arena').onclick=()=>{view='arena';load();window.scrollTo(0,0)};
  $('#toggle-theme').onclick=()=>{saved.theme=saved.theme==='dark'?'light':'dark';persist();document.body.dataset.theme=saved.theme};
  note.addEventListener('input',()=>{if(view!=='lesson')return;saved.notes[selected]=note.value;persist();$('#note-feedback').textContent='Saved locally ✓'});
  $('#backup-btn').onclick=()=>{const data=new Blob([JSON.stringify({version:1,data:saved},null,2)],{type:'application/json'});const url=URL.createObjectURL(data);const a=document.createElement('a');a.href=url;a.download='fullstack-academy-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};
  $('#import-btn').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const j=JSON.parse(await f.text());if(j.version!==1||!j.data||typeof j.data!=='object')throw Error('Invalid backup version');const incoming=j.data;saved={...saved,complete:{...saved.complete,...(incoming.complete||{})},quizzes:{...saved.quizzes,...(incoming.quizzes||{})},notes:{...saved.notes,...(incoming.notes||{})},rubrics:{...saved.rubrics,...(incoming.rubrics||{})},reflections:{...saved.reflections,...(incoming.reflections||{})}};persist();load();alert('Progress restored on this device.')}catch(err){alert('Invalid backup: '+err.message)}e.target.value=''};
  $('#open-sidebar').onclick=()=>$('#sidebar').classList.add('show');$('#close-sidebar').onclick=()=>$('#sidebar').classList.remove('show');
  document.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName?.toLowerCase();if(['input','textarea','select'].includes(tag))return;if(e.key==='/'){e.preventDefault();search.focus();return}if(e.key===']'){e.preventDefault();selectLesson(AUTHOR_IDS[(Math.max(0,AUTHOR_IDS.indexOf(selected))+1)%AUTHOR_IDS.length]);return}if(e.key==='['){e.preventDefault();selectLesson(AUTHOR_IDS[(Math.max(0,AUTHOR_IDS.indexOf(selected))+AUTHOR_IDS.length-1)%AUTHOR_IDS.length]);return}});
  load();
})();
